/**
 * Wayland Input Adapter for Termux:X11
 *
 * Bridges Android input events to Wayland protocol events.
 * Thread-safe: Android main thread pushes events to a queue;
 * Wayland display thread drains the queue and sends protocol events.
 */

#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <android/log.h>

/* Include paths for Wayland headers.
 * wayland-server.h is in the wayland submodule source.
 * wayland-server-protocol.h is generated by wayland-scanner during build.
 * The CMake build system adds both directories to the include path. */
#include "wayland-server.h"
#include "wayland-server-protocol.h"
#include "input.h"

#define LOG_TAG "LorieWlInput"
#define log(...) __android_log_print(ANDROID_LOG_DEBUG, LOG_TAG, __VA_ARGS__)
#define loge(...) __android_log_print(ANDROID_LOG_ERROR, LOG_TAG, __VA_ARGS__)

/* Event queue for thread-safe cross-thread communication */
#define INPUT_QUEUE_SIZE 256

typedef enum {
    INPUT_EVENT_POINTER_MOTION,
    INPUT_EVENT_POINTER_BUTTON,
    INPUT_EVENT_POINTER_AXIS,
    INPUT_EVENT_KEYBOARD_KEY,
    INPUT_EVENT_TOUCH_DOWN,
    INPUT_EVENT_TOUCH_UP,
    INPUT_EVENT_TOUCH_MOTION,
    INPUT_EVENT_SET_FOCUS,
    INPUT_EVENT_SET_POINTER_FOCUS,
} input_event_type_t;

typedef struct {
    input_event_type_t type;
    union {
        struct { double x, y; } pointer_motion;
        struct { uint32_t button; bool pressed; } pointer_button;
        struct { uint32_t axis; double value; } pointer_axis;
        struct { uint32_t keycode; bool pressed; } keyboard_key;
        struct { int id; double x, y; } touch_down;
        struct { int id; } touch_up;
        struct { int id; double x, y; } touch_motion;
        struct { struct wl_surface *surface; } set_focus;
        struct { struct wl_surface *surface; double x, y; } set_pointer_focus;
    } data;
} input_event_t;

typedef struct {
    input_event_t events[INPUT_QUEUE_SIZE];
    size_t head;
    size_t tail;
    pthread_mutex_t mutex;
} input_queue_t;

/* Per-client input resource tracking */
struct input_client {
    struct wl_client *client;
    struct wl_resource *pointer;
    struct wl_resource *keyboard;
    struct wl_resource *touch;
    struct wl_list link;
};

/* Global input state */
static struct {
    struct wl_display *display;
    struct wl_global *seat_global;

    /* Resource lists */
    struct wl_list clients;    /* struct input_client */

    /* Focus state (accessed only from Wayland thread during dispatch) */
    struct wl_surface *keyboard_focus;
    struct wl_surface *pointer_focus;
    double pointer_x;
    double pointer_y;

    /* Event queue (shared between threads) */
    input_queue_t queue;

    /* Serial counter for enter/leave events */
    uint32_t last_serial;
} input;

