/**
 * Drain the event queue and dispatch Wayland protocol events.
 * Must be called from the Wayland display thread.
 */
void lorie_wl_input_dispatch(void) {
    input_event_t ev;
    while (queue_pop(&ev)) {
        switch (ev.type) {
            case INPUT_EVENT_POINTER_MOTION:
                dispatch_pointer_motion(ev.data.pointer_motion.x,
                                         ev.data.pointer_motion.y);
                break;
            case INPUT_EVENT_POINTER_BUTTON:
                dispatch_pointer_button(ev.data.pointer_button.button,
                                         ev.data.pointer_button.pressed);
                break;
            case INPUT_EVENT_POINTER_AXIS:
                dispatch_pointer_axis(ev.data.pointer_axis.axis,
                                       ev.data.pointer_axis.value);
                break;
            case INPUT_EVENT_KEYBOARD_KEY:
                dispatch_keyboard_key(ev.data.keyboard_key.keycode,
                                       ev.data.keyboard_key.pressed);
                break;
            case INPUT_EVENT_TOUCH_DOWN:
                dispatch_touch_down(ev.data.touch_down.id,
                                     ev.data.touch_down.x,
                                     ev.data.touch_down.y);
                break;
            case INPUT_EVENT_TOUCH_UP:
                dispatch_touch_up(ev.data.touch_up.id);
                break;
            case INPUT_EVENT_TOUCH_MOTION:
                dispatch_touch_motion(ev.data.touch_motion.id,
                                       ev.data.touch_motion.x,
                                       ev.data.touch_motion.y);
                break;
            case INPUT_EVENT_SET_FOCUS:
                dispatch_set_focus(ev.data.set_focus.surface);
                break;
            case INPUT_EVENT_SET_POINTER_FOCUS:
                dispatch_set_pointer_focus(ev.data.set_pointer_focus.surface,
                                            ev.data.set_pointer_focus.x,
                                            ev.data.set_pointer_focus.y);
                break;
        }
    }
}
